css:
/* ==== INTERFACE ====
reference: style:05-bento-grid
方向：Bento Grid 现代数理排版。借鉴参考图中模块尺度对比、规整间隙与精炼数据卡片质感；结合用户要求的“蓝色与青色”构建精密数理调色盘。以高对比海军蓝基底（--bg）、深沉科技白（--text）、明亮青色（--cyan）与科技电蓝（--blue）构成主控关系。大圆角微框单元（.nt-bento-cell）支持模块化组织、高光图表与交互微件。
token --bg: #0b111e (深邃靛蓝底色)
token --text: #e6f0fa (正文主色)
token --muted: #7993b4 (次要提示与图注)
token --cyan: #00e5ff (强调与现期增长高光)
token --blue: #2979ff (次强调、基准与控件焦点)
token --border: rgba(64, 130, 200, 0.18) (Bento 模块微质感细边框)
token --font-sans: "NTF-inter", "NTF-noto-sans-sc", sans-serif (正文与控件混排)
token --font-display: "NTF-space-grotesk", "NTF-noto-sans-sc", sans-serif (标题与强对比数字)
class .nt-title: 主题标题 (font-size: var(--fs-h1, 40px), font-weight: 700, 行高 1.25)
class .nt-bento-cell: Bento 盒单元，提供半透明微青蓝底质与 18px 圆角边界
class .nt-slider: 原生交互滑块定制外观，青色导轨与高亮拖扭
class .nt-chart-line: 用于 SVG 增长曲线的基础描边与发光层
class .nt-metric: 关键指标与终值金额展示组件
variant opening: 封面强强调，提供深空径向渐变辉光背景
默认：全页面固定逻辑 1600x900 画布，无图优雅回退
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-space-grotesk";
  src: url("fonts/library/space-grotesk/face-0.ttf");
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #0b111e;
  --bg-subtle: #111a2d;
  --text: #e6f0fa;
  --text-pure: #ffffff;
  --muted: #7993b4;
  --muted-dim: #455d7a;

  --cyan: #00e5ff;
  --cyan-dim: rgba(0, 229, 255, 0.15);
  --cyan-glow: rgba(0, 229, 255, 0.35);
  --blue: #2979ff;
  --blue-dim: rgba(41, 121, 255, 0.15);
  --blue-glow: rgba(41, 121, 255, 0.35);

  --border: rgba(64, 130, 200, 0.22);
  --border-bright: rgba(0, 229, 255, 0.45);
  --focus: #00e5ff;

  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-display: "NTF-space-grotesk", "NTF-noto-sans-sc", sans-serif;

  --fs-hero: 56px;
  --fs-h1: 38px;
  --fs-h2: 24px;
  --fs-lead: 20px;
  --fs-body: 16px;
  --fs-sec: 14px;
  --fs-tick: 12px;

  --chart-curve-stroke: 4px;
  --chart-point-radius: 6px;
}

/* 舞台基底 */
#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(circle at 15% 15%, rgba(0, 229, 255, 0.08) 0%, transparent 45%),
    radial-gradient(circle at 85% 85%, rgba(41, 121, 255, 0.1) 0%, transparent 50%),
    linear-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 40px 40px, 40px 40px;
  background-position: 0 0, 0 0, -1px -1px, -1px -1px;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.6;
  box-sizing: border-box;
  overflow: hidden;
}

/* 开篇变体背景 */
html[data-variant="opening"] #stage {
  background-image: 
    radial-gradient(circle at 50% 30%, rgba(0, 229, 255, 0.14) 0%, transparent 60%),
    radial-gradient(circle at 80% 80%, rgba(41, 121, 255, 0.18) 0%, transparent 55%),
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 40px 40px, 40px 40px;
}

/* Bento 风格通用排版角色 */
.nt-hero-title {
  font-family: var(--font-display);
  font-size: var(--fs-hero);
  font-weight: 700;
  line-height: 1.15;
  color: var(--text-pure);
  letter-spacing: -0.02em;
  margin: 0;
}

.nt-title {
  font-family: var(--font-display);
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.25;
  color: var(--text-pure);
  letter-spacing: -0.015em;
  margin: 0;
}

.nt-subtitle {
  font-family: var(--font-sans);
  font-size: var(--fs-h2);
  font-weight: 500;
  line-height: 1.4;
  color: var(--cyan);
  margin: 0;
}

.nt-lead {
  font-size: var(--fs-lead);
  color: var(--muted);
  line-height: 1.55;
  margin: 0;
}

.nt-body {
  font-size: var(--fs-body);
  color: var(--text);
  line-height: 1.6;
}

.nt-sec {
  font-size: var(--fs-sec);
  color: var(--muted);
  line-height: 1.5;
}

.nt-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--cyan-dim);
  border: 1px solid var(--border-bright);
  color: var(--cyan);
  font-family: var(--font-display);
  font-size: var(--fs-sec);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Bento 盒模型单元 */
.nt-bento-grid {
  display: grid;
  gap: 20px;
  box-sizing: border-box;
}

.nt-bento-cell {
  background: rgba(17, 26, 45, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 24px;
  box-sizing: border-box;
  position: relative;
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.nt-bento-cell:hover {
  border-color: rgba(0, 229, 255, 0.35);
}

.nt-bento-cell.is-highlight {
  background: linear-gradient(145deg, rgba(17, 26, 45, 0.85), rgba(12, 34, 60, 0.85));
  border-color: var(--border-bright);
  box-shadow: 0 8px 32px -4px var(--cyan-glow);
}

/* 指标展现 (Bento 核心大字单元) */
.nt-metric {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.nt-metric-val {
  font-family: var(--font-display);
  font-size: 44px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--text-pure);
  letter-spacing: -0.03em;
}

.nt-metric-val.is-cyan {
  color: var(--cyan);
  text-shadow: 0 0 24px var(--cyan-glow);
}

.nt-metric-label {
  font-size: var(--fs-sec);
  color: var(--muted);
  font-weight: 500;
}

/* 原生表单与控件 */
.nt-control-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.nt-slider-wrapper {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
}

.nt-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 4px;
  background: #18253a;
  outline: none;
  border: 1px solid var(--border);
  transition: border-color 0.2s;
}

.nt-slider:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 2px var(--cyan-dim);
}

.nt-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--cyan);
  border: 2px solid #ffffff;
  cursor: pointer;
  box-shadow: 0 0 12px var(--cyan-glow);
  transition: transform 0.15s ease, background-color 0.15s;
}

.nt-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: #ffffff;
}

.nt-slider::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--cyan);
  border: 2px solid #ffffff;
  cursor: pointer;
  box-shadow: 0 0 12px var(--cyan-glow);
}

.nt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: 12px;
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  background: rgba(41, 121, 255, 0.12);
  color: var(--text-pure);
  transition: all 0.2s ease;
}

.nt-btn:hover {
  background: rgba(41, 121, 255, 0.24);
  border-color: var(--blue);
}

.nt-btn:focus-visible {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 2px var(--cyan-glow);
}

.nt-btn-cyan {
  background: var(--cyan);
  border-color: var(--cyan);
  color: #05101d;
  font-weight: 700;
}

.nt-btn-cyan:hover {
  background: #4df0ff;
  box-shadow: 0 0 16px var(--cyan-glow);
}

/* 图表与几何曲线共享样式 */
.nt-chart-svg {
  overflow: visible;
  width: 100%;
  height: 100%;
}

.nt-chart-grid {
  stroke: rgba(255, 255, 255, 0.07);
  stroke-width: 1px;
  stroke-dasharray: 4 4;
}

.nt-chart-axis {
  stroke: rgba(255, 255, 255, 0.2);
  stroke-width: 1.5px;
}

.nt-chart-tick-text {
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  fill: var(--muted);
  text-anchor: middle;
  dominant-baseline: middle;
}

.nt-chart-line {
  fill: none;
  stroke: var(--cyan);
  stroke-width: var(--chart-curve-stroke);
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 8px var(--cyan-glow));
}

.nt-chart-line-baseline {
  fill: none;
  stroke: var(--blue);
  stroke-width: 2px;
  stroke-dasharray: 5 5;
  opacity: 0.65;
}

.nt-chart-point {
  fill: #0b111e;
  stroke: var(--cyan);
  stroke-width: 3px;
  r: var(--chart-point-radius);
  transition: r 0.2s ease;
}

.nt-chart-point:hover {
  r: 8px;
  fill: var(--cyan);
}

.nt-chart-fill-area {
  fill: url(#nt-growth-gradient);
  opacity: 0.35;
}

/* 动效降级保障 */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
